package com.hosteldekho.repository; import com.hosteldekho.entity.Room; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*; public interface RoomRepository extends JpaRepository<Room,Long>{List<Room> findByHostelId(Long hostelId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select r from Room r where r.id=:id") Optional<Room> findByIdForUpdate(@Param("id") Long id);}
